import { randomBytes } from "node:crypto";
import type { ClawforceConfig } from "./types.js";
import { getRuntimeEngineAdapter } from "./engines/registry.js";

export function generateEnv(config: ClawforceConfig): string {
  const gatewayToken = randomBytes(32).toString("hex");

  const hooksToken = randomBytes(32).toString("hex");

  const models = config.models;
  const credentialMode = models.credential_mode ?? "env";

  const lines = [
    "# Generated by Clawforce",
    `# Deployment: ${config.name}`,
    "# DO NOT COMMIT THIS FILE TO VERSION CONTROL",
    "",
    `GATEWAY_TOKEN=${gatewayToken}`,
    `HOOKS_TOKEN=${hooksToken}`,
  ];

  if (credentialMode === "env") {
    const providerKeys = Object.entries(models.provider_keys ?? {}).sort((a, b) =>
      a[0].localeCompare(b[0])
    );
    for (const [provider, apiKey] of providerKeys) {
      lines.push(`${toProviderApiKeyEnvName(provider)}=${apiKey}`);
    }
    if (models.auth_profile) {
      lines.push(
        "# NOTE: models.auth_profile is configured but ignored because credential_mode=env",
      );
    }
  } else {
    lines.push("# Credential mode uses OpenClaw auth profile, not provider env vars");
    lines.push(`OPENCLAW_AUTH_PROFILE=${models.auth_profile ?? ""}`);
    if (models.provider_keys && Object.keys(models.provider_keys).length > 0) {
      lines.push(
        "# NOTE: models.provider_keys is configured but ignored because credential_mode=auth_profile",
      );
    }
  }

  if (config.dashboard?.auth?.enabled) {
    const authSecret = randomBytes(32).toString("hex");
    lines.push("");
    lines.push("# Dashboard authentication");
    lines.push(`AUTH_SECRET=${authSecret}`);
  }

  if (config.alerts?.notifications?.email?.password) {
    lines.push(`CLAWFORCE_ALERTS_EMAIL_PASSWORD=${config.alerts.notifications.email.password}`);
  }

  if (config.local_model?.location === "host") {
    const adapter = getRuntimeEngineAdapter(config.local_model.engine);
    lines.push("");
    lines.push("# Host runtime endpoint");
    lines.push(`${adapter.hostEnvVarName}=${adapter.resolveHostRuntimeUrl(config.local_model)}`);
  }

  return lines.join("\n") + "\n";
}

function toProviderApiKeyEnvName(provider: string): string {
  return `${provider.toUpperCase().replace(/[^A-Z0-9]/g, "_")}_API_KEY`;
}
